import{_ as t,o as a,c as i,ao as n}from"./chunks/framework.7i-0i5HL.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"MRIReco.jl","tagline":"Magnetic Resonance Imaging Reconstruction in Julia","image":{"src":"/logo.png","alt":"MRIReco.jl"},"actions":[{"theme":"brand","text":"Getting Started","link":"/gettingStarted"},{"theme":"alt","text":"Tutorials","link":"/generated/tutorials/direct"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/MagneticResonanceImaging/MRIReco.jl"}]},"features":[{"title":"Raw Data and Files","details":"Read and write ISMRMRD files, read Bruker datasets and prepare raw data for reconstruction.","link":"/generated/howto/load_save"},{"title":"Iterative Reconstruction","details":"Reconstruct undersampled data with the solvers and regularization terms of RegularizedLeastSquares.jl.","link":"/generated/tutorials/iterative"},{"title":"Parallel Imaging","details":"Estimate coil sensitivities with ESPIRiT and reconstruct one image from the data of all coils, also combined with compressed sensing.","link":"/generated/tutorials/multicoil"},{"title":"GPU Acceleration","details":"Run reconstructions on a GPU by setting the reconstruction parameter <code>arrayType</code>.","link":"/generated/howto/gpu"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),r={name:"index.md"};function s(o,e,l,d,c,g){return a(),i("div",null,[...e[0]||(e[0]=[n('<p>MRIReco.jl is a framework for MRI image reconstruction written in Julia. It provides data types for raw data and for k-space data prepared for reconstruction, encoding operators, and direct as well as iterative reconstruction methods, including parallel imaging and compressed sensing. Further packages read and write raw data files, generate sampling patterns, estimate coil sensitivities and simulate data.</p><h2 id="Packages" tabindex="-1">Packages <a class="header-anchor" href="#Packages" aria-label="Permalink to &quot;Packages {#Packages}&quot;">​</a></h2><p>MRIReco.jl consists of several packages that are developed in the same repository and registered individually. The last column lists the packages of this repository that each package depends on. MRIReco re-exports its dependencies MRIBase and MRIOperators, so their names are available after <code>using MRIReco</code>; the other packages are independent of MRIReco and are installed and loaded separately.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Package</th><th style="text-align:left;">Purpose</th><th style="text-align:left;">Depends on</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./API/MRIReco">MRIReco</a></td><td style="text-align:left;">Image reconstruction</td><td style="text-align:left;">MRIBase, MRIOperators</td></tr><tr><td style="text-align:left;"><a href="./API/MRIBase">MRIBase</a></td><td style="text-align:left;">Data types for raw data, acquisition data and trajectories</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><a href="./API/MRIOperators">MRIOperators</a></td><td style="text-align:left;">Encoding operators</td><td style="text-align:left;">MRIBase</td></tr><tr><td style="text-align:left;"><a href="./API/MRIFiles">MRIFiles</a></td><td style="text-align:left;">Reading and writing raw data files</td><td style="text-align:left;">MRIBase</td></tr><tr><td style="text-align:left;"><a href="./API/MRISampling">MRISampling</a></td><td style="text-align:left;">Undersampling patterns</td><td style="text-align:left;">MRIBase</td></tr><tr><td style="text-align:left;"><a href="./API/MRICoilSensitivities">MRICoilSensitivities</a></td><td style="text-align:left;">Coil sensitivity estimation and coil compression</td><td style="text-align:left;">MRIBase</td></tr><tr><td style="text-align:left;"><a href="./API/MRISimulation">MRISimulation</a></td><td style="text-align:left;">Simulation of MRI data</td><td style="text-align:left;">MRIBase, MRIOperators</td></tr></tbody></table><h2 id="How-the-Documentation-Is-Organized" tabindex="-1">How the Documentation Is Organized <a class="header-anchor" href="#How-the-Documentation-Is-Organized" aria-label="Permalink to &quot;How the Documentation Is Organized {#How-the-Documentation-Is-Organized}&quot;">​</a></h2><ul><li><p><a href="/MRIReco.jl/dev/gettingStarted#Getting-Started">Getting Started</a> shows how to install the packages and run a first reconstruction.</p></li><li><p>The tutorials walk through complete reconstructions step by step.</p></li><li><p>The how-to guides show how to solve specific tasks, grouped by package.</p></li><li><p>The explanations describe the design of the packages and the concepts behind them.</p></li><li><p>The reference lists the API of each package.</p></li></ul><h2 id="Citing-MRIReco.jl" tabindex="-1">Citing MRIReco.jl <a class="header-anchor" href="#Citing-MRIReco.jl" aria-label="Permalink to &quot;Citing MRIReco.jl {#Citing-MRIReco.jl}&quot;">​</a></h2><p>If you use MRIReco.jl in your work, please cite</p><blockquote><p>T. Knopp and M. Grosser, &quot;MRIReco.jl: An MRI reconstruction framework written in Julia&quot;, Magnetic Resonance in Medicine 86, 1633–1646 (2021), <a href="https://doi.org/10.1002/mrm.28792" target="_blank" rel="noreferrer">doi:10.1002/mrm.28792</a>.</p></blockquote><p>A BibTeX entry is in <a href="https://github.com/MagneticResonanceImaging/MRIReco.jl/blob/master/MRIReco.bib" target="_blank" rel="noreferrer"><code>MRIReco.bib</code></a>.</p><h2 id="Getting-Help" tabindex="-1">Getting Help <a class="header-anchor" href="#Getting-Help" aria-label="Permalink to &quot;Getting Help {#Getting-Help}&quot;">​</a></h2><p>Questions are welcome in <a href="https://github.com/MagneticResonanceImaging/MRIReco.jl/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a>, and bugs can be reported as <a href="https://github.com/MagneticResonanceImaging/MRIReco.jl/issues" target="_blank" rel="noreferrer">issues</a>. To contribute changes, see the <a href="./contributing">contributing guide</a>.</p>',12)])])}const u=t(r,[["render",s]]);export{h as __pageData,u as default};
